<?php require_once __DIR__.'/../config/auth.php'; require_login(); $error=''; if ($_SERVER['REQUEST_METHOD']==='POST') { verify_csrf(); $old=$_POST['old_password']??''; $new=$_POST['new_password']??''; $confirm=$_POST['confirm_password']??''; $q=db()->prepare('SELECT password FROM users WHERE id_user=?'); $q->execute([current_user()['id_user']]); $u=$q->fetch(); if (!$u || !password_verify($old,$u['password'])) $error='Password lama salah.'; elseif (strlen($new)<8) $error='Password baru minimal 8 karakter.'; elseif ($new!==$confirm) $error='Konfirmasi password tidak sama.'; else { $q=db()->prepare('UPDATE users SET password=? WHERE id_user=?'); $q->execute([password_hash($new,PASSWORD_BCRYPT),current_user()['id_user']]); flash('success','Password berhasil diganti.'); redirect('../'.dashboard_path(current_user()['role'])); } } $page_title='Ganti Password'; require '../includes/header.php'; require '../includes/sidebar.php'; require '../includes/flash.php'; ?><div class="card p-4 col-md-7"><h4>Ganti Password</h4><?php if($error): ?><div class="alert alert-danger"><?= e($error) ?></div><?php endif; ?><form method="post"><?= csrf_field() ?><div class="mb-3"><label>Password lama</label><input type="password" name="old_password" class="form-control" required></div><div class="mb-3"><label>Password baru</label><input type="password" name="new_password" class="form-control" minlength="8" required></div><div class="mb-3"><label>Konfirmasi password</label><input type="password" name="confirm_password" class="form-control" required></div><button class="btn btn-primary">Simpan</button></form></div><?php require '../includes/footer.php';
